/* v0.2: explicit phases, visual council decisions and local recovery. */
const previousRender=render,previousRole=renderRole,previousDraw=draw;
const shieldImages=new Map();let transitioning=false;
function shieldImage(country){if(!country.shield)return null;if(!shieldImages.has(country.shield)){const img=new Image();img.onload=()=>draw();img.src=country.shield;shieldImages.set(country.shield,img);}return shieldImages.get(country.shield);}
function pendingTreaties(){return state.renewals||[];}
render=function(){previousRender();renderStages();};
renderRole=function(){previousRole();if(state.phase!=='implement'){$('rolePanel').querySelectorAll('input,select,button').forEach(el=>el.disabled=true);const note=document.createElement('p');note.className='phase-help';note.textContent=state.phase==='decide'?'Planning is locked. Use the decision cards above to choose what happens next.':'This turn is complete. Start the next Implement phase to make new plans.';$('rolePanel').prepend(note);}};
draw=function(){previousDraw();const z=camera.w/1200;ctx.save();ctx.scale(1200/camera.w,700/camera.h);ctx.translate(-camera.x,-camera.y);if($('highlightCountry')?.checked){state.cells.filter(c=>c.land&&c.country!==active).forEach(c=>{poly(c);ctx.fillStyle='#f4f1e8a8';ctx.fill();});state.cells.filter(c=>c.land&&c.country===active).forEach(c=>{poly(c);ctx.strokeStyle='#263f34';ctx.lineWidth=.65*z;ctx.stroke();});}state.cells.filter(c=>c.buildings.includes('city')||c.buildings.includes('village')).forEach(c=>{ctx.font=`${13*z}px sans-serif`;ctx.textAlign='center';ctx.fillStyle='#182f25';ctx.fillText(c.buildings.includes('city')?'▣':'⌂',c.point[0],c.point[1]+13*z);});state.countries.forEach(c=>{const im=shieldImage(c);if(im?.complete&&im.naturalWidth){ctx.drawImage(im,c.capital[0]-12*z,c.capital[1]-30*z,24*z,24*z);}});ctx.restore();};
function renderStages(){const p=state.phase||'implement';$('phaseSteps').innerHTML=[['implement','1','🛠','Implement','Make your plans'],['decide','2','🤝','Decide','Meet, talk & vote'],['results','3','📜','Results','See what changed']].map(([key,num,icon,title,help])=>`<div class="phase-step ${p===key?'current':''}"><span>${icon}</span><div><strong>${num}. ${title}</strong><small>${help}</small></div></div>`).join('');$('advance').textContent=p==='implement'?'Go to Decide →':p==='decide'?'Show Results →':'Next turn →';$('phaseDescription').textContent=p==='implement'?'Choose policies, plan buildings, and give movement orders. Nothing fights yet.':p==='decide'?'Regiments have moved. Choose how to respond to meetings, answer treaty offers, and vote on new settlements.':'Read the results. Production, research, supply, and battles are finished for this turn.';$('turn').textContent=String(p==='results'?state.turn-1:state.turn).padStart(2,'0');$('season').textContent=['SPRING','SUMMER','AUTUMN','WINTER'][((p==='results'?state.turn-1:state.turn)-1)%4]+' · YEAR '+(1+Math.floor(((p==='results'?state.turn-1:state.turn)-1)/4));
const c=ctry();$('shieldPreview').replaceChildren();if(c.shield){const img=document.createElement('img');img.src=c.shield;img.alt=c.name+' shield';$('shieldPreview').append(img);}else $('shieldPreview').textContent='♜';$('shieldUpload').disabled=p!=='implement';$('removeShield').disabled=p!=='implement'||!c.shield;
$('settlements').innerHTML=state.cells.filter(x=>x.country===active&&(x.buildings.includes('city')||x.buildings.includes('village'))).map(x=>`<button data-settlement="${x.id}">${x.buildings.includes('city')?'🏙':'🏡'} ${esc(x.settlement|| (x.buildings.includes('city')?'City':'Village')+' '+x.id)}</button>`).join('')||'<small>No settlements yet. Propose a village on your own land.</small>';document.querySelectorAll('[data-settlement]').forEach(b=>b.onclick=()=>{cellId=Number(b.dataset.settlement);const point=state.cells[cellId].point;camera={x:point[0]-150,y:point[1]-87.5,w:300,h:175};render();});
const panel=$('decisions');panel.innerHTML='';panel.hidden=p!=='decide';if(p!=='decide')return;
let html='<h2>🤝 Council decisions</h2><p class="role-intro">In this host test, switch between all countries and roles yourself. Each choice is saved.</p>';
html+=state.decisions.map((d,i)=>{const a=state.regiments.find(r=>r.id===d.a),b=state.regiments.find(r=>r.id===d.b);return `<article class="decision"><h3>⚑ Meeting at cell ${d.cell}</h3><p>${esc(a.name)} meets ${esc(b.name)}.</p>${[a,b].map(r=>`<label>${esc(r.name)}<select data-encounter="${i}" data-regiment="${r.id}">${options([['defend','🛡 Stay peaceful / defend if attacked'],['avoid','↩ Try to leave'],['target','⚔ Attack this other country'],['all','⚔ Attack every non-ally here']],r.stance)}</select></label>`).join('')}<button data-confirm="${i}" ${d.confirmed?'disabled':''}>${d.confirmed?'✓ Choices confirmed':'Confirm both choices'}</button><small>Allies cannot attack each other. Changing orders reopens related encounter confirmations.</small></article>`;}).join('');
html+=state.proposals.map((proposal,i)=>`<article class="decision"><h3>${proposal.type==='city'?'🏙':'🏡'} Proposed ${proposal.type} · Cell ${proposal.cell}</h3><p>${esc(state.countries[proposal.country].name)} · Resources are reserved. All three roles must agree.</p>${['economy','research','military'].map(role=>`<div class="vote-row"><b>${{economy:'💰 Economy',research:'📚 Research',military:'🛡 Military'}[role]}</b><button data-vote="${i}" data-role-vote="${role}" data-value="yes" class="${proposal.votes[role]===true?'chosen':''}">Yes</button><button data-vote="${i}" data-role-vote="${role}" data-value="no" class="${proposal.votes[role]===false?'chosen':''}">No</button></div>`).join('')}</article>`).join('');
html+=state.offers.map((o,i)=>`<article class="decision"><h3>📜 Treaty offer</h3><p>${esc(state.countries[o.from].name)} offers ${o.kind==='ally'?'an alliance':'peace'} to ${esc(state.countries[o.to].name)}.</p><button data-treaty="${i}" data-answer="yes">Receiving country: accept</button><button data-treaty="${i}" data-answer="no">Decline</button></article>`).join('');
html+=pendingTreaties().map((t,i)=>`<article class="decision"><h3>⏳ Renew alliance?</h3><p>${esc(state.countries[t.a].name)} + ${esc(state.countries[t.b].name)} · Both countries must agree to extend it for 4 turns.</p>${[t.a,t.b].map(id=>`<div class="vote-row"><b>${esc(state.countries[id].name)}</b><button data-renew="${i}" data-country-vote="${id}" data-value="yes" class="${t.votes[id]===true?'chosen':''}">Extend</button><button data-renew="${i}" data-country-vote="${id}" data-value="no" class="${t.votes[id]===false?'chosen':''}">End</button></div>`).join('')}</article>`).join('');
if(!state.decisions.length&&!state.proposals.length&&!state.offers.length&&!pendingTreaties().length)html+='<p>🕊 No encounters or council votes this turn. You can show Results.</p>';panel.innerHTML=html;
panel.querySelectorAll('[data-encounter]').forEach(el=>el.onchange=()=>action(()=>{const r=state.regiments.find(r=>r.id===Number(el.dataset.regiment)),d=state.decisions[Number(el.dataset.encounter)],other=state.regiments.find(x=>x.id===(d.a===r.id?d.b:d.a));r.stance=el.value;r.target=other.country;state.decisions.filter(d=>d.a===r.id||d.b===r.id).forEach(d=>d.confirmed=false);}));panel.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>action(()=>state.decisions[Number(b.dataset.confirm)].confirmed=true));panel.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>action(()=>Game.vote(state,Number(b.dataset.vote),b.dataset.roleVote,b.dataset.value==='yes')));panel.querySelectorAll('[data-treaty]').forEach(b=>b.onclick=()=>action(()=>{const i=Number(b.dataset.treaty);if(b.dataset.answer==='yes')Game.accept(state,i,state.offers[i].to);else state.offers.splice(i,1);}));panel.querySelectorAll('[data-renew]').forEach(b=>b.onclick=()=>action(()=>pendingTreaties()[Number(b.dataset.renew)].votes[b.dataset.countryVote]=b.dataset.value==='yes'));
}
async function phaseTransition(){if(transitioning)return;transitioning=true;try{if(state.phase==='decide')Game.ready(state);await Checkpoints.save(state,'Before '+(state.phase==='implement'?'movement':state.phase==='decide'?'results':'next turn'));if(state.phase==='implement')Game.prepare(state);else if(state.phase==='decide')Game.advance(state);else Game.next(state);moving=false;save();render();notify('Checkpoint saved. '+(state.phase==='decide'?'Review the decision cards.':state.phase==='results'?'Your results are ready below.':'Make your next plans.'));if(state.phase==='decide')$('decisions').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){notify(e.message);}finally{transitioning=false;}}
$('advance').onclick=phaseTransition;$('confirmTurn').onclick=phaseTransition;
$('highlightCountry').onchange=draw;$('focusCountry').onclick=()=>{const cells=state.cells.filter(c=>c.country===active&&c.land),points=cells.flatMap(c=>c.polygon),x=Math.min(...points.map(p=>p[0])),y=Math.min(...points.map(p=>p[1])),w=Math.max(...points.map(p=>p[0]))-x,h=Math.max(...points.map(p=>p[1]))-y,width=Math.min(1200,Math.max(w+50,(h+50)*12/7));camera={x:x+w/2-width/2,y:y+h/2-width*7/24,w:width,h:width*7/12};draw();};
$('shieldUpload').onclick=()=>$('shieldFile').click();$('removeShield').onclick=()=>action(()=>ctry().shield='','Shield removed.');$('shieldFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const id=active;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a PNG, JPEG or WebP image under 8 MB.');const bitmap=await createImageBitmap(file),c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d'),scale=Math.min(128/bitmap.width,128/bitmap.height);x.drawImage(bitmap,(128-bitmap.width*scale)/2,(128-bitmap.height*scale)/2,bitmap.width*scale,bitmap.height*scale);bitmap.close();if(state.phase!=='implement')throw Error('Upload shields during Implement.');state.countries[id].shield=c.toDataURL('image/png');save();render();notify('Shield saved for '+state.countries[id].name+'.');}catch(e){notify(e.message);}finally{e.target.value='';}};
$('checkpoints').onclick=async()=>{try{const saves=await Checkpoints.list();$('checkpointList').innerHTML=saves.length?saves.map(x=>`<article class="mini-card"><strong>${esc(x.label)} · Turn ${x.turn}</strong><p>v${esc(x.release)} · ${esc(x.phase)} · ${esc(new Date(x.date).toLocaleString())}</p><button data-rollback="${x.id}">Restore this checkpoint</button></article>`).join(''):'<p>Your first checkpoint is saved automatically when you change phases.</p>';$('checkpointDialog').showModal();document.querySelectorAll('[data-rollback]').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this checkpoint? Your current campaign will first be saved as another checkpoint.'))return;try{const item=await Checkpoints.get(Number(b.dataset.rollback)),restored=Game.validate(JSON.parse(JSON.stringify(item.state)));await Checkpoints.save(state,'Before restoring checkpoint');state=restored;active=Math.min(active,state.countries.length-1);cellId=state.regiments[0]?.cell||0;regimentId=null;moving=false;saveBlocked=false;save();render();$('checkpointDialog').close();notify('Checkpoint restored. Your former campaign is also in the checkpoint list.');}catch(e){notify(e.message);}});}catch(e){notify(e.message);}};$('closeCheckpoints').onclick=()=>$('checkpointDialog').close();$('manualCheckpoint').onclick=async()=>{try{await Checkpoints.save(state,'Manual checkpoint');notify('Checkpoint saved. Use Restore turn to return here.');}catch(e){notify(e.message);}};
render();
